//! Native B03D40/B04BC0 Bus gain cache refresh and active-child propagation.
use crate::{audio_bus_registry::Bus,audio_bus_effects_bank as effects,audio_bus_bank::Error};
use std::collections::{BTreeMap,BTreeSet};
#[derive(Debug)]pub struct Group{pub children:Vec<u32>,pub active:[u16;2]}
#[derive(Debug,Default)]pub struct Graph{pub buses:BTreeMap<u32,Bus>,pub caches:BTreeMap<u32,effects::Cache>,pub groups:BTreeMap<u32,Group>}
pub trait Gain{fn gain(&mut self,node:u32,args:[u32;2],graph:&Graph)->Result<f32,Error>;fn root(&mut self,kind:u32,bits:u32,graph:&Graph)->Result<(),Error>;fn bus(&mut self,id:u32,bits:u32,graph:&Graph)->Result<(),Error>;}
impl Graph{
 fn validate(&self,id:u32,active:&mut BTreeSet<u32>)->Result<(),Error>{if !active.insert(id){return Err(Error::Backend("cyclic Bus refresh hierarchy"));}let b=self.buses.get(&id).ok_or(Error::Backend("missing Bus refresh node"))?;if b.reference!=id || id==0{return Err(Error::UnresolvedReference);}if b.word(0)!=0xff1380{return Err(Error::WrongClass);}if b.word(0x18)!=0 && !self.caches.contains_key(&b.word(0x18)){return Err(Error::MissingEffectsCache(b.word(0x18)));}if b.word(0x1c)!=0{let group=self.groups.get(&b.word(0x1c)).ok_or(Error::Backend("missing Bus refresh group"))?;for child in &group.children{let child_bus=self.buses.get(child).ok_or(Error::Backend("missing Bus refresh child"))?;if child_bus.word(0x1c)!=0{let child_group=self.groups.get(&child_bus.word(0x1c)).ok_or(Error::Backend("missing Bus refresh child group"))?;if child_group.active!=[0,0]{self.validate(*child,active)?;}}}}active.remove(&id);Ok(())}
 pub(crate) fn processing(&self,id:u32)->bool{let b=&self.buses[&id];let effects=b.word(0x18)!=0 && self.caches[&b.word(0x18)].notification().effect_ids.iter().any(|v|*v!=0);effects || b.word(0x60)!=0 || b.raw[0x2f]&4!=0 || b.word(0x24)==0 || b.raw[0x2f]&8!=0}
 fn update(&mut self,id:u32,backend:&mut impl Gain)->Result<(),Error>{let processing=self.processing(id);if processing{let gain=backend.gain(id,[0,4],self)?;let b=self.buses.get_mut(&id).unwrap();b.raw[0xc4]|=0x20;if b.word(0x24)==0{backend.root(u32::from(b.raw[0xc4]>>7),gain.to_bits(),self)?;}else{backend.bus(b.word(8),gain.to_bits(),self)?;}}self.buses.get_mut(&id).unwrap().raw[0xc4]&=!1;let bc=if processing{0.}else{backend.gain(id,[0,4],self)?};self.buses.get_mut(&id).unwrap().set_word(0xbc,bc.to_bits());let c0=backend.gain(id,[1,0],self)?;let b=self.buses.get_mut(&id).unwrap();b.raw[0xc4]|=1;b.set_word(0xc0,c0.to_bits());let group=b.word(0x1c);let children=if group==0{vec![]}else{self.groups[&group].children.clone()};for child in children{let group=self.buses[&child].word(0x1c);if group!=0 && self.groups[&group].active!=[0,0]{self.update(child,backend)?;}}Ok(())}
 pub fn changed(&mut self,id:u32,backend:&mut impl Gain)->Result<(),Error>{self.validate(id,&mut BTreeSet::new())?;self.update(id,backend)}
}
pub struct Backend<'a,B,G>{pub dependencies:&'a mut B,pub graph:&'a mut Graph,pub gain:&'a mut G}
impl<B:effects::Backend,G:Gain>effects::Backend for Backend<'_,B,G>{fn allocate(&mut self,n:u32)->Result<Option<effects::Allocation>,Error>{self.dependencies.allocate(n)}fn slot(&mut self,b:&mut Bus,i:u32)->Result<(),Error>{self.dependencies.slot(b,i)}fn mask(&mut self,b:&mut Bus,v:u32,m:u32)->Result<(),Error>{self.dependencies.mask(b,v,m)}fn apply(&mut self,b:&Bus,v:u32,m:u32)->Result<(),Error>{self.dependencies.apply(b,v,m)}fn changed(&mut self,b:&mut Bus,c:&effects::Cache)->Result<(),Error>{if !self.graph.buses.contains_key(&b.reference){return Err(Error::Backend("missing live Bus refresh node"));}self.graph.buses.insert(b.reference,b.clone());self.graph.caches.insert(b.word(0x18),c.clone());let out=self.graph.changed(b.reference,self.gain);*b=self.graph.buses[&b.reference].clone();out}}
#[cfg(test)]mod tests{use super::*;struct Trace{profile:usize,calls:Vec<serde_json::Value>}impl Gain for Trace{fn gain(&mut self,n:u32,args:[u32;2],_:&Graph)->Result<f32,Error>{let index=[0x30001000,0x30002000,0x30002100].iter().position(|v|*v==n).unwrap();let value=[0.,1.,-2.5][self.profile]+index as f32*0.25+args[0]as f32*0.5;self.calls.push(serde_json::json!({"kind":"gain","node":n,"args":args,"bits":value.to_bits()}));Ok(value)}fn root(&mut self,k:u32,b:u32,_:&Graph)->Result<(),Error>{self.calls.push(serde_json::json!({"kind":"root_gain","args":[k,b]}));Ok(())}fn bus(&mut self,id:u32,b:u32,_:&Graph)->Result<(),Error>{self.calls.push(serde_json::json!({"kind":"bus_gain","args":[id,b]}));Ok(())}}
#[test]fn audio_bus_effect_changed_cache_hierarchy_matches3456_native_cases(){let p:serde_json::Value=serde_json::from_str(&crate::audio_test_fixture("data/4.20/audio_bus_effects_changed_contract.json")).unwrap();assert_eq!(p["case_count"],3456);for(case,row)in p["cases"].as_array().unwrap().iter().enumerate(){let refs=[0x30001000,0x30002000,0x30002100];let mut graph=Graph::default();let mask=[0,1,2,7][row["effect_profile"].as_u64().unwrap()as usize];for(i,r)in refs.into_iter().enumerate(){let bus=Bus{reference:r,raw:crate::audio_spatial_controls::tests::hex(row["before"][i].as_str().unwrap())};let mut cache=effects::Cache{raw:[0;36]};cache.raw[4..8].copy_from_slice(&(if mask&(1<<i)!=0{777u32}else{0}).to_le_bytes());graph.caches.insert(bus.word(0x18),cache);graph.buses.insert(r,bus);graph.groups.insert([0x30004000,0x30004100,0x30004200][i],Group{children:if i==0{vec![refs[1],refs[2]]}else{vec![]},active:if i==0{[0,0]}else{[row["active"][i-1][0].as_u64().unwrap()as u16,row["active"][i-1][1].as_u64().unwrap()as u16]}});}let mut b=Trace{profile:row["gain_profile"].as_u64().unwrap()as usize,calls:vec![]};graph.changed(refs[0],&mut b).unwrap();assert_eq!(serde_json::json!(b.calls),row["calls"],"order {case}");for(i,r)in refs.into_iter().enumerate(){assert_eq!(graph.buses[&r].raw,crate::audio_spatial_controls::tests::hex::<200>(row["after"][i].as_str().unwrap()),"node {case}/{i}");}}}}
